1	import { Fragment, useState } from "react";
2	import CreativeInventoryTab from "@/components/game/CreativeInventoryTab";
3	import EnchantingColumn from "@/components/game/EnchantingColumn";
4	import ItemIcon from "@/components/game/ItemIcon";
5	import { itemTooltipFor, type TooltipContent, useItemTooltip } from "@/components/game/ItemTooltip";
6	import PixelImg from "@/components/game/PixelImg";
7	import { CONTAINER_SLOT_BASE } from "@/lib/game/engine/commands";
8	import { ingredientStatus } from "@/lib/game/inventory";
9	import { itemSourceHint } from "@/lib/game/itemSources";
10	import { ARMOR_SLOT_LABELS, ARMOR_SLOTS, createSlot, ITEM_DEF_BY_ID } from "@/lib/game/items";
11	import { groupRecipes } from "@/lib/game/recipes";
12	import { itemIconUrl } from "@/lib/ui/sprites";
13	import type { GameMode } from "@/lib/game/gameModes";
14	import type { EnchantmentId, EquippedArmor, InventorySlot, Recipe } from "@/lib/game/types";
15	
16	type InventoryPanelProps = {
17	  inventory: InventorySlot[];
18	  equippedArmor: EquippedArmor;
19	  selectedHotbarSlot: number;
20	  hotbarSlots: number;
21	  recipes: Recipe[];
22	  craftingStation: "furnace" | "villager" | "brewing" | "enchanting" | null;
23	  /** Current game mode — Creative swaps the recipe book for the item palette. */
24	  gameMode: GameMode;
25	  /** Contents of the open chest, or null when no chest is open. */
26	  container: InventorySlot[] | null;
27	  /** Current XP level + per-enchant cost, for the enchanting panel. */
28	  xpLevel: number;
29	  enchantCost: number;
30	  canCraft: (recipe: Recipe) => boolean;
31	  onSwapSlots: (fromIndex: number, toIndex: number) => void;
32	  /** Moves a slot across the inventory/chest boundary (chest indices offset by CONTAINER_SLOT_BASE). */
33	  onMoveStack: (fromIndex: number, toIndex: number) => void;
34	  onToggleEquipArmor: (index: number) => void;
35	  onCraft: (recipe: Recipe) => void;
36	  onEnchant: (id: EnchantmentId) => void;
37	  /** Pulls a full stack of an item from the Creative palette into the inventory. */
38	  onGiveItem: (itemId: string) => void;
39	};
40	
41	const STATION_LABELS: Record<NonNullable<Recipe["station"]>, string> = {
42	  furnace: "Furnace",
43	  villager: "Villager",
44	  brewing: "Brewing Stand"
45	};
46	
47	const labelFor = (slotId: string): string => ITEM_DEF_BY_ID[slotId]?.label ?? slotId;
48	
49	/**
50	 * Hover text for a recipe. A craftable recipe just names itself; a station-locked
51	 * one says which station it needs; an unaffordable one lists each ingredient as
52	 * have/need and, for every shortfall, a "how to obtain" hint. The detail is what
53	 * the user can't read from the tiny grayscale icons alone.
54	 */
55	function recipeTooltip(recipe: Recipe, inventory: InventorySlot[], locked: boolean, craftable: boolean): TooltipContent {
56	  if (locked) return { title: labelFor(recipe.result.slotId), lines: [`Requires ${STATION_LABELS[recipe.station!]}`] };
57	  if (craftable) return { title: recipe.label };
58	
59	  const status = ingredientStatus(inventory, recipe);
60	  const lines = status.map((s) => `${labelFor(s.slotId)}  ${s.have} / ${s.need}${s.have < s.need ? ` (need ${s.need - s.have} more)` : " ✓"}`);
61	  for (const s of status) {
62	    if (s.have >= s.need) continue;
63	    const hint = itemSourceHint(s.slotId);
64	    if (hint) lines.push(`→ ${labelFor(s.slotId)}: ${hint}`);
65	  }
66	  return { title: labelFor(recipe.result.slotId), lines };
67	}
68	
69	/**
70	 * The survival inventory: armor column, 27-slot storage grid, hotbar row, and
71	 * a recipe book where every entry shows ingredient icons and the result.
72	 * Items move by clicking one slot and then another (click-to-swap); clicking
73	 * an armor item toggles equipping it instead.
74	 */
75	export default function InventoryPanel({
76	  inventory,
77	  equippedArmor,
78	  selectedHotbarSlot,
79	  hotbarSlots,
80	  recipes,
81	  craftingStation,
82	  gameMode,
83	  container,
84	  xpLevel,
85	  enchantCost,
86	  canCraft,
87	  onSwapSlots,
88	  onMoveStack,
89	  onToggleEquipArmor,
90	  onCraft,
91	  onEnchant,
92	  onGiveItem
93	}: InventoryPanelProps) {
94	  const [pendingIndex, setPendingIndex] = useState<number | null>(null);
95	  const { tooltip, bind } = useItemTooltip();
96	
97	  // While a chest is open, moves span both grids (chest slots are offset by
98	  // CONTAINER_SLOT_BASE); otherwise a swap stays within the player inventory.
99	  const slotAt = (index: number): InventorySlot | undefined => (index >= CONTAINER_SLOT_BASE ? container?.[index - CONTAINER_SLOT_BASE] : inventory[index]);
100	
101	  const onSlotClick = (index: number) => {
102	    const slot = slotAt(index);
103	    if (!slot) return;
104	    // Clicking armor in the player inventory equips it; chest slots only move.
105	    if (index < CONTAINER_SLOT_BASE && slot.kind === "armor" && slot.count > 0) {
106	      onToggleEquipArmor(index);
107	      setPendingIndex(null);
108	      return;
109	    }
110	
111	    if (pendingIndex === null) {
112	      setPendingIndex(index);
113	      return;
114	    }
115	    if (pendingIndex === index) {
116	      setPendingIndex(null);
117	      return;
118	    }
119	    (container ? onMoveStack : onSwapSlots)(pendingIndex, index);
120	    setPendingIndex(null);
121	  };
122	
123	  const isEquipped = (slot: InventorySlot) => slot.kind === "armor" && !!slot.id && equippedArmor[slot.armorSlot ?? "helmet"] === slot.id;
124	
125	  const renderSlot = (slot: InventorySlot, idx: number, extraClass = "") => {
126	    const isChest = idx >= CONTAINER_SLOT_BASE;
127	    const name = isChest ? `Chest slot ${idx - CONTAINER_SLOT_BASE + 1}` : `Slot ${idx + 1}`;
128	    return (
129	      <button
130	        key={`inv-slot-${idx}`}
131	        className={["inv-slot", extraClass, pendingIndex === idx ? "pending" : "", isEquipped(slot) ? "equipped" : ""].filter(Boolean).join(" ")}
132	        onClick={() => onSlotClick(idx)}
133	        {...bind(itemTooltipFor(slot))}
134	        aria-label={slot.id && slot.count > 0 ? `${name}: ${slot.label}` : `${name}: empty`}
135	      >
136	        <ItemIcon slot={slot} size={32} />
137	      </button>
138	    );
139	  };
140	
141	  const hotbar = inventory.slice(0, hotbarSlots);
142	  const storage = inventory.slice(hotbarSlots);
143	
144	  // A recipe is locked when it needs a station the player isn't using; it can be
145	  // made right now only when it's both unlocked and affordable. The recipe book
146	  // groups by category and floats the "make now" recipes to the top of each group.
147	  const stationLocked = (recipe: Recipe) => !!recipe.station && recipe.station !== craftingStation;
148	  const canMakeNow = (recipe: Recipe) => !stationLocked(recipe) && canCraft(recipe);
149	  const recipeGroups = groupRecipes(recipes, canMakeNow);
150	
151	  const renderRecipe = (recipe: Recipe) => {
152	    const locked = stationLocked(recipe);
153	    const craftable = !locked && canCraft(recipe);
154	    return (
155	      <button
156	        key={recipe.id}
157	        className={`recipe-entry${craftable ? "" : " is-disabled"}`}
158	        // Not the native `disabled` attribute: disabled buttons swallow hover
159	        // events, so the tooltip explaining what's missing would never appear.
160	        onClick={() => {
161	          if (craftable) onCraft(recipe);
162	        }}
163	        aria-disabled={!craftable}
164	        aria-label={recipe.label}
165	        {...bind(recipeTooltip(recipe, inventory, locked, craftable))}
166	      >
167	        <span className="recipe-ingredients">
168	          {recipe.cost.map((cost) => (
169	            <ItemIcon key={`${recipe.id}-${cost.slotId}`} slot={createSlot(cost.slotId, cost.count)} size={24} />
170	          ))}
171	        </span>
172	        <span className="recipe-arrow" aria-hidden>
173	          →
174	        </span>
175	        <ItemIcon slot={createSlot(recipe.result.slotId, recipe.result.count)} size={24} />
176	      </button>
177	    );
178	  };
179	
180	  return (
181	    <div className="inventory-panel">
182	      <div className="inventory-columns">
183	        <div className="inventory-main">
184	          {container ? (
185	            <div className="chest-section">
186	              <div className="inventory-heading">Chest</div>
187	              <div className="inv-grid chest-grid" data-testid="chest-grid">
188	                {container.map((slot, i) => renderSlot(slot, CONTAINER_SLOT_BASE + i))}
189	              </div>
190	            </div>
191	          ) : null}
192	          <div className="inventory-heading">Inventory</div>
193	          <div className="inventory-upper">
194	            <div className="armor-column">
195	              {ARMOR_SLOTS.map((armorSlot) => {
196	                const equippedId = equippedArmor[armorSlot];
197	                const equippedIndex = equippedId ? inventory.findIndex((slot) => slot.id === equippedId && slot.count > 0) : -1;
198	                const equippedItem = equippedIndex >= 0 ? inventory[equippedIndex] : undefined;
199	                return (
200	                  <button
201	                    key={`armor-${armorSlot}`}
202	                    className={equippedItem ? "inv-slot armor-slot filled" : "inv-slot armor-slot"}
203	                    onClick={() => equippedIndex >= 0 && onToggleEquipArmor(equippedIndex)}
204	                    {...bind(equippedItem ? itemTooltipFor(equippedItem) : { title: `${ARMOR_SLOT_LABELS[armorSlot]} (empty)` })}
205	                    aria-label={equippedItem ? `${ARMOR_SLOT_LABELS[armorSlot]}: ${equippedItem.label}` : `${ARMOR_SLOT_LABELS[armorSlot]}: empty`}
206	                  >
207	                    {equippedItem ? (
208	                      <ItemIcon slot={equippedItem} size={32} />
209	                    ) : (
210	                      <span className="armor-ghost">
211	                        <PixelImg src={itemIconUrl(armorSlot)} alt="" size={32} aria-hidden />
212	                      </span>
213	                    )}
214	                  </button>
215	                );
216	              })}
217	            </div>
218	            <div className="inventory-hint">
219	              Click one slot, then another to move items.
220	              <br />
221	              Click armor to equip or unequip it.
222	            </div>
223	          </div>
224	          <div className="inv-grid storage" data-testid="storage-grid">
225	            {storage.map((slot, offset) => renderSlot(slot, offset + hotbarSlots))}
226	          </div>
