 * optional, so a pre-Hardcore save simply loads as a normal, non-hardcore world
 * (see restoreHardcore/restoreGameOver).
 */
export function migrateSaveV9toV10(save: SaveDataV9): SaveData {
  return { ...save, version: 10 };
}

// Storage is injectable so save logic can be tested without a browser.
export function readSave(saveKey: string, storage: Storage = localStorage): SaveData | null {
  try {
    const raw = storage.getItem(saveKey);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as
      | SaveData
      | SaveDataV9
      | SaveDataV8
      | SaveDataV7
      | SaveDataV6
      | SaveDataV5
      | SaveDataV4
      | SaveDataV3
      | SaveDataV2
      | SaveDataV1;
    if (!parsed || !Number.isFinite(parsed.seed) || !Array.isArray(parsed.changes)) return null;
    let migrated: SaveDataV2 | SaveDataV3 | SaveDataV4 | SaveDataV5 | SaveDataV6 | SaveDataV7 | SaveDataV8 | SaveDataV9 | SaveData =
      parsed.version === 1 ? migrateSaveV1toV2(parsed) : parsed;
    if (migrated.version === 2) migrated = migrateSaveV2toV3(migrated);
    if (migrated.version === 3) migrated = migrateSaveV3toV4(migrated);
    if (migrated.version === 4) migrated = migrateSaveV4toV5(migrated);
    if (migrated.version === 5) migrated = migrateSaveV5toV6(migrated);
    if (migrated.version === 6) migrated = migrateSaveV6toV7(migrated);
    if (migrated.version === 7) migrated = migrateSaveV7toV8(migrated);
    if (migrated.version === 8) migrated = migrateSaveV8toV9(migrated);
    if (migrated.version === 9) migrated = migrateSaveV9toV10(migrated);
    if (migrated.version !== 10) return null;
    return migrated;
  } catch {
    return null;
  }
}

export function writeSave(saveKey: string, data: SaveData, storage: Storage = localStorage): void {
  storage.setItem(saveKey, JSON.stringify(data));
}

export function inventorySlotsSnapshot(inventory: InventorySlot[]): SavedSlot[] {
  return inventory.map((slot) => ({ id: slot.id, count: slot.count, durability: slot.durability, enchantments: slot.enchantments }));
}

// Every known enchantment id, keyed so a new enchantment can't be forgotten here.
const VALID_ENCHANT_IDS: Record<EnchantmentId, true> = {
  sharpness: true,
  protection: true,
  efficiency: true,
  unbreaking: true
};

/** Validates persisted enchantments: known ids and integer levels clamped to 1..max; undefined when none survive. */
function restoreEnchantments(saved: SavedSlot["enchantments"]): Enchantment[] | undefined {
  if (!Array.isArray(saved)) return undefined;
  const out: Enchantment[] = [];
  for (const entry of saved) {
    if (!entry || typeof entry.id !== "string" || !Object.hasOwn(VALID_ENCHANT_IDS, entry.id)) continue;
    if (!Number.isFinite(entry.level) || Math.floor(entry.level) < 1) continue;
    out.push({ id: entry.id, level: Math.min(ENCHANT_MAX_LEVEL, Math.floor(entry.level)) });
  }
  return out.length > 0 ? out : undefined;
}

/**
 * Rebuilds one slot from its saved snapshot: drops unknown ids, clamps the
 * count, and clamps/defaults durability for gear (a non-positive saved
 * durability means the piece broke and is dropped). Returns an empty slot for
 * anything invalid. Shared by inventory and container restore.
 */
function restoreSlot(saved: SavedSlot | undefined): InventorySlot {
  if (!saved?.id || saved.count <= 0 || !ITEM_DEF_BY_ID[saved.id]) return createEmptySlot();
  const slot = createSlot(saved.id, Math.min(maxStackSizeForItem(saved.id), Math.max(0, Math.floor(saved.count))));
  if ((slot.kind === "tool" || slot.kind === "weapon" || slot.kind === "armor") && slot.maxDurability) {
    if (typeof saved.durability === "number") {
      const loaded = Math.floor(saved.durability);
      if (loaded <= 0) return createEmptySlot();
      slot.durability = Math.max(1, Math.min(slot.maxDurability, loaded));
    } else {
      slot.durability = slot.maxDurability;
    }
    // Enchantments live only on durable gear; validated against the known set.
    const enchantments = restoreEnchantments(saved.enchantments);
    if (enchantments) slot.enchantments = enchantments;
  }
  return slot;
}

/** Snapshots non-empty chest containers for persistence (empty chests carry no data). */
export function serializeContainers(containers: Map<number, InventorySlot[]>): SavedContainer[] {
  const out: SavedContainer[] = [];
  for (const [index, slots] of containers) {
    if (!slots.some((slot) => slot.id && slot.count > 0)) continue;
    out.push({ index, slots: inventorySlotsSnapshot(slots) });
  }

// XP & enchanting. XP accrues from kills, ore mining, and fishing (the per-mob
// and per-ore tables live in mobXp.ts / systems/xp.ts, like mobLoot.ts), banked
// as points; XP_PER_LEVEL points make one level. Levels are spent at an
// enchanting table — ENCHANT_COST_LEVELS per application, up to ENCHANT_MAX_LEVEL.
// Each enchant is a flat per-level modifier at one existing seam.
export const XP_PER_LEVEL = 10;
export const FISHING_XP = 2;
export const ENCHANT_MAX_LEVEL = 3;
export const ENCHANT_COST_LEVELS = 3; // XP levels per enchant application
export const SHARPNESS_DAMAGE_PER_LEVEL = 2; // +melee damage per level
export const PROTECTION_DEFENSE_PER_LEVEL = 2; // +defense points per level (feeds armorReduction)
export const EFFICIENCY_SPEED_PER_LEVEL = 0.3; // mining speed ×(1 + level × this)
export const UNBREAKING_SKIP_PER_LEVEL = 0.2; // chance per level to skip durability wear

// Safety & persistence
export const STUCK_RESET_SECONDS = 0.8;
export const AUTOSAVE_INTERVAL_MS = 15000;
// Legacy single-world save key. Since the multi-world feature, each world owns
// its own `minecraft_world_save_<id>` blob (see lib/game/worlds.ts); this key
// is only read once by the legacy migration (lib/game/legacyMigration.ts) and
// is otherwise unused.
export const SAVE_KEY = "minecraft_save_v7";

// The deterministic world-generation baseline. Bumped whenever worldgen
// changes, so old block-diffs (which index against generated terrain) can't be
// applied to a different baseline: v6 added dungeons; v7 added deep-cave lava
// lakes; v8 added shallow coal ore. Each world records the WORLDGEN_VERSION it
// was generated under; a world whose recorded version differs from this constant
// has its block-diffs discarded and is rebooted from its stored seed
// (lib/game/worlds.ts). The save *schema* (SaveData, currently v6) is independent
// of this — lighting is a derived cache and lava is worldgen, so neither is
// persisted, and additive schema bumps (like v6's status effects) don't touch it.
export const WORLDGEN_VERSION = 8;

// Rendering
export const RENDER_RADIUS = 90;
export const RENDER_GRID = 20;
// Third-person camera boom, clamped against walls with a margin that keeps
// the near plane (0.1) out of the blocking block.

